class Metrics:
    @staticmethod
    def threshold_crossing_time(y: np.ndarray, threshold: float, start_day: int = 0) -> float:
        if y is None or len(y) == 0:
            return float("nan")
        start = max(0, int(start_day))
        for t in range(start, len(y)):
            if y[t] >= threshold:
                return float(t - start)
        return float("nan")

